// One-off: converts ../question-paper.html (generated by the exam-question-paper skill)
// into a draft bank file. topic and explanation are left empty for enrichment.
// Usage: node scripts/import-paper.ts <paper.html> <unit> <out.json>
import { readFileSync, writeFileSync } from "node:fs";

const [src, unitArg, out] = process.argv.slice(2);
const unit = Number(unitArg);
const html = readFileSync(src, "utf8");

const text = (s: string) =>
  s.replace(/<[^>]+>/g, "").replace(/&middot;/g, "·").replace(/&amp;/g, "&").replace(/\s+/g, " ").trim();
const all = (re: RegExp, s: string) => [...s.matchAll(re)].map((m) => m[1]);

const key = new Map<number, { answer: string; code?: string }>();
for (const m of html.matchAll(/<div class="key-cell"><span class="n">Q(\d+)\.<\/span>\s*([a-d])(?:<span class="code">(.*?)<\/span>)?<\/div>/g))
  key.set(Number(m[1]), { answer: m[2], code: m[3] ? text(m[3]) : undefined });

const questions = all(/<article class="q">([\s\S]*?)<\/article>/g, html).map((body) => {
  const n = Number(body.match(/<span class="qn">Q(\d+)\.<\/span>/)![1]);
  const stem = text(body.match(/<p class="stem">([\s\S]*?)<\/p>/)![1].replace(/<span class="qn">.*?<\/span>/, ""));
  const paras = all(/<p>([\s\S]*?)<\/p>/g, body).map(text);
  const options = all(/<div>([\s\S]*?)<\/div>/g, body.match(/<div class="opts">([\s\S]*?)<\/div>\s*$/)?.[1] ?? body)
    .map(text)
    .map((o) => o.replace(/^[a-d]\)\s*/, ""));
  const items = all(/<li>([\s\S]*?)<\/li>/g, body).map(text);
  const rows = [...body.matchAll(/<tr><td>([\s\S]*?)<\/td><td>([\s\S]*?)<\/td><\/tr>/g)];
  const k = key.get(n)!;

  let type: string;
  const q: Record<string, unknown> = { id: `u${String(unit).padStart(2, "0")}-${String(n).padStart(3, "0")}`, unit, topic: "" };
  if (stem.startsWith("Assertion (A):")) type = "ar";
  else if (rows.length) type = "matching";
  else if (items.length && /sequence|order/i.test(paras.join(" ") + stem)) type = "sequencing";
  else if (items.length) type = "statements";
  else type = "mcq";
  q.type = type;
  q.stem = stem;
  if (type === "ar") q.reason = paras.find((p) => p.startsWith("Reason (R):"));
  if (items.length) q.items = items;
  if (rows.length) {
    q.listI = rows.map((r) => text(r[1]).replace(/^[A-D]\.\s*/, ""));
    q.listII = rows.map((r) => text(r[2]).replace(/^\d\.\s*/, ""));
  }
  const prompt = paras.find((p) => /^(Choose|Which of the above|Select)/.test(p));
  if (prompt) q.prompt = prompt;
  q.options = options.slice(-4);
  q.answer = k.answer;
  if (k.code) q.code = k.code;
  q.explanation = "";
  return q;
});

writeFileSync(out, JSON.stringify(questions, null, 2) + "\n");
console.log(`wrote ${questions.length} questions to ${out}`);
